// English for the interface. How entries are matched is described at the top of i18n.js.
//
// To add a text: put the Chinese exactly as the page shows it (without a final 。) under "exact"; when it carries
// a value, under "patterns" with {x} (any text), {#n} (a number) or {@t} (a time) where the value stands.
// `python3 test/i18n_harvest.py` lists what the sources hold and no entry covers.
//
// Glossary — keep to it:
//   素材 asset · 素材库 Library · 工程 project · 流水线 Pipeline · 模型 avatar · 素体 base · 改模 avatar editing
//   衣服 Outfits · 头发 Hair · 配饰 Accessories · 道具 Props · 皮肤 Skins · 材质 Materials · 表情 Expressions
//   光影 Lighting · 互动 Interactions · 面捕 Face tracking · 插件 plugin (Unity) / package (VPM)
//   装配 fit (onto the avatar) · 菜单 menu · 开关 toggle · 互斥 one at a time · 部件 part · 配色 color
//   装配方案 preset · 验收 review · 体检 check (pre-upload check) · 同步参数 synced parameters · 位 bits
//   已购 purchased / purchases · 网盘 netdisk · 百度网盘 Baidu Netdisk · 分享 share · 提取码 access code
//   封面 cover · 愿望单 wish list · 闲鱼 Xianyu · 识图 vision · 视觉模型 vision model · 服务商 provider
//   Names stay as they are: Booth, Gumroad, Jinxxy, Modular Avatar, lilToon, ALCOM, VCC, UnitySkills, VRChat SDK.
//   Sentence case; no full stop on labels, buttons and one-line notices.
