    // --- copied links offered on every tab (1.7.8) ---
    "已复制闲鱼链接": "Xianyu link copied",
    "已复制 Booth 链接": "Booth link copied",
    "复制闲鱼、Booth、网盘链接后提示打开或收录": "Offer to open or save copied Xianyu, Booth and netdisk links",
    // --- 闲鱼: its own view or the default browser, and the copied share (1.7.7) ---
    "可收录百度网盘、Google Drive、Dropbox 的分享": "Shares on Baidu Netdisk, Google Drive and Dropbox can be saved",
    "暂不支持该网盘，可收录百度网盘、Google Drive、Dropbox 的分享": "This netdisk isn't supported yet. Shares on Baidu Netdisk, Google Drive and Dropbox can be saved",
    "以管理员身份运行时内置浏览器无法启动，请以普通方式启动本软件": "The built-in browser can't start while the app runs as administrator. Start the app normally",
    "软件位于前台时，会查看剪贴板中是否有闲鱼、Booth 或网盘分享链接，并提示打开或收录，可在设置中关闭": "While the app is in front, it checks the clipboard for Xianyu, Booth and netdisk share links and offers to open or save them. You can turn this off in Settings",
    "页面在新标签页中打开的链接（如商品详情）会显示为独立窗口": "Links a page opens in a new tab (an item's page, for example) are shown in a window of their own",
    "卖家发送网盘分享后，复制完整的分享文本（含链接和提取码），再点击「收录网盘链接」": "When the seller sends a netdisk share, copy the whole share text (link and access code), then click “Save netdisk link”",
    "卖家发来网盘分享后，复制完整的分享文本（含链接和提取码），回到此页签点击「收录网盘链接」": "When the seller sends a netdisk share, copy the whole share text (link and access code), then come back to this tab and click “Save netdisk link”",
    "已在默认浏览器中打开": "Opened in your default browser",
    "闲鱼页面的打开方式": "How Xianyu pages open",
    "自 1.7.7 起，闲鱼页面不再使用软件的内置浏览器（Booth、网盘等页面仍在其中打开），改为以下两种方式之一": "From 1.7.7 on, Xianyu pages no longer use the app's built-in browser (Booth, netdisk and other pages still open in it). They open in one of the two ways below",
    "在软件内打开": "Open inside the app",
    "使用独立的内嵌浏览器": "Uses a separate embedded browser",
    "软件不向页面注入或执行脚本，不读写 Cookie，不使用代理设置，也不保存登录状态，通常每次启动软件后需重新扫码登录": "The app injects and runs no script in the pages, does not read or write cookies, does not use the proxy setting and does not keep the sign-in, so you usually scan the QR code again each time the app starts",
    "闲鱼页面交给系统的默认浏览器，与平时使用浏览器相同": "Xianyu pages are handed to your default browser, just like browsing normally",
    "两种方式下，复制卖家发来的网盘分享文本后，均可在「闲鱼」页签一键收录": "Either way, after you copy the netdisk share text a seller sent, you can save it with one click on the Xianyu tab",
    "此前的版本中，有用户在内置浏览器登录闲鱼后账号被平台限制": "In earlier versions, a user's account was restricted by the platform after signing in to Xianyu in the built-in browser",
    "新的内嵌浏览器已去除可能导致该问题的因素，但仍可能被网站识别为应用内浏览器，软件无法保证不触发平台的风控": "The new embedded browser removes what may have caused this, but the site may still recognise it as an in-app browser, and the app cannot guarantee that the platform's risk control will not be triggered",
    "账号较为重要时，建议选择默认浏览器": "If the account matters to you, choose the default browser",
    "之后可随时在「闲鱼」页签左侧的「打开方式」中更改": "You can change this at any time under “How pages open” on the left of the Xianyu tab",
    "设置未能保存": "Couldn't save the setting",
    "复制链接后将提示打开或收录": "Copied links will be offered for opening or saving",
    "已关闭复制提示": "Copy prompt turned off",
    "登录、聊天和下单均可在此完成": "You can sign in, chat and order here",
    "闲鱼页面在默认浏览器中打开": "Xianyu pages open in your default browser",
    "闲鱼页面使用独立的内嵌浏览器，软件不保存其登录状态，通常每次启动软件后需重新扫码登录": "Xianyu pages use a separate embedded browser. The app does not keep its sign-in, so you usually scan the QR code again each time the app starts",
    "卖家发送网盘分享后，复制完整的分享文本（含链接和提取码），页面上方将提示收录；也可在复制后点击「收录网盘链接」": "When the seller sends a netdisk share, copy the whole share text (link and access code) and a prompt to save it appears above the page. You can also click “Save netdisk link” after copying",
    "复制链接后提示打开或收录": "Offer to open or save copied links",
    "软件位于前台时查看剪贴板，只识别闲鱼、Booth 和网盘分享链接，不保存其他内容": "The clipboard is checked while the app is in front. Only Xianyu, Booth and netdisk share links are recognised, and nothing else is kept",
    "打开方式": "How pages open",
