    "查看说明": "Read the note",
    "本机当前无法在软件内显示闲鱼页面（需要 WebView2、软件以自带窗口运行，且未以管理员身份运行），闲鱼页面在默认浏览器中打开": "This computer can't show Xianyu pages inside the app right now (that needs WebView2 and the app running in its own window, not as administrator), so Xianyu pages open in your default browser",
