    "本机当前无法在软件内显示闲鱼页面（需要 WebView2、软件以自带窗口运行，且未以管理员身份运行）": "This computer can't show Xianyu pages inside the app right now (that needs WebView2 and the app running in its own window, not as administrator)",
    "卖家发来网盘分享后，复制完整的分享文本（含链接和提取码），回到此页签，页面上方将提示收录": "When the seller sends a netdisk share, copy the whole share text (link and access code), then come back to this tab: a prompt to save it appears above the page",
