    "点击卡片上的「流水线」，可将已导入的衣服、头发、配饰和道具装配到模型，按设定的层级生成菜单开关和图标，并可继续通过 AI 执行其他改模操作": "“Pipeline” on a card fits imported outfits, hair, accessories and props onto the avatar, builds menu toggles and icons in the layout you set, and lets you go on editing the avatar with AI",
