    "流水线需要在 Unity 工程中运行": "The pipeline works on a Unity project",
    "可一键新建包含 VRChat SDK 和常用插件的基础工程": "You can create a starter project with the VRChat SDK and the usual tools in one go",
    "自动列出工程 Assets 中已导入的素材": "Lists the assets imported into the project's Assets",
    "勾选要装配的素材，类别有误可在下拉列表中修改": "Tick the ones to fit. If a kind is wrong, change it in its list",
