    "手动添加路径：Assets/店铺名/素材名（也可填写 prefab 路径）": "Add a path by hand: Assets/Shop/Asset (a prefab path works too)",
    "按类别将素材装配到模型，并生成菜单开关和图标": "Fits the assets onto the avatar by kind and builds menu toggles and icons",
    "素体 → 场景中无模型时自动放入": "Bases → placed when the scene has no avatar",
    "衣服 → 互斥切换，支持部件开关": "Outfits → one at a time, with part toggles",
    "头发 → 独立互斥组": "Hair → a group of its own, one at a time",
    "配饰 → 开关，默认显示": "Accessories → toggle, shown by default",
    "道具 → 开关，默认隐藏": "Props → toggle, hidden by default",
    "皮肤 → 材质切换，互斥": "Skins → material swap, one at a time",
    "表情 / 光影 / 互动 → 原样放置，菜单归入分类": "Expressions / Lighting / Interactions → placed as they are, menus filed by category",
    "面捕 → 核对素体，可直接放置的放置，其余提示安装步骤": "Face tracking → base checked; placed when it can be, otherwise the install steps are shown",
    "菜单层级": "Menu layout",
    "主菜单 > {分类} > {素材} > {开关}": "Main menu > {category} > {asset} > {toggles}",
    "恢复默认": "Reset",
    "用 > 分隔各层级": "Separate levels with >",
    "{分类} 对应素材的类别（衣服、头发、皮肤、道具、光影等），{素材} 为每个素材单独一层，{开关} 为该素材的开关；去掉 {素材} 后，每个素材仅生成一个总开关": "{category} stands for the asset's category (Outfits, Hair, Skins, Props, Lighting …), {asset} gives each asset a level of its own, {toggles} is where that asset's toggles go; without {asset}, each asset gets a single toggle",
    "也可用自然语言描述，由 AI 按描述排列": "You can also describe the layout in plain words and let the AI arrange it",
    "不使用 AI，按网格名称分组（速度快、无费用，分组较粗）": "Without AI: group parts by mesh name (fast and free, rougher grouping)",
    "运行流水线": "Run pipeline",
    "执行记录显示在下方": "The run log is shown below",
    "完成后请在 Unity 中检查，确认无误后再保存场景": "When it is done, check the result in Unity and save the scene only once it looks right",
    "检查模型能否上传、有无显示异常，并列出各项参数。不改动场景": "Checks whether the avatar can be uploaded and whether anything looks wrong, and lists its figures. The scene is not changed",
    "上传前体检": "Pre-upload check",
    "继续向 AI 下达指令，例如：将鞋子的开关改名为“凉鞋”；为外套添加红色配色；检查是否有丢失的材质。按 Ctrl+Enter 发送": "Tell the AI what to do next, e.g. rename the shoes toggle to “Sandals”; add a red color for the coat; check for missing materials. Ctrl+Enter sends",
