    // --- the AI service: providers, errors ---
    "在阿里云百炼（bailian.console.aliyun.com）申请 API Key。控制台提供的是带工作空间的地址（https://…maas.aliyuncs.com/compatible-mode/v1）时，请填写该地址。常用模型：qwen-plus、qwen-max、qwen3.8-max": "Get an API key at Alibaba Cloud Bailian (bailian.console.aliyun.com). If the console gives you an address with a workspace (https://…maas.aliyuncs.com/compatible-mode/v1), enter that one. Common models: qwen-plus, qwen-max, qwen3.8-max",
    "在智谱开放平台（bigmodel.cn）申请 API Key。常用模型：glm-5.3、glm-4.7；免费模型：glm-4.7-flash。识图使用其视觉模型（glm-4.6v-flash 免费）": "Get an API key at the Zhipu open platform (bigmodel.cn). Common models: glm-5.3, glm-4.7; free: glm-4.7-flash. Vision uses its vision models (glm-4.6v-flash is free)",
    "在 Kimi 开放平台（platform.kimi.com）申请 API Key。常用模型：kimi-k3、kimi-k2.6，均支持识图": "Get an API key at the Kimi open platform (platform.kimi.com). Common models: kimi-k3, kimi-k2.6; both read images",
    "OpenAI 官方，或任何兼容 OpenAI 接口的服务（中转站、本地的 Ollama / LM Studio 等）：填写该服务提供的接口地址和 Key": "OpenAI itself, or any service with an OpenAI-compatible API (relays, a local Ollama / LM Studio …): enter the endpoint and key that service gives you",
    "Anthropic 官方，或兼容 Anthropic 接口的服务：填写该服务提供的接口地址和 Key": "Anthropic itself, or a service with an Anthropic-compatible API: enter the endpoint and key that service gives you",
    "DeepSeek 的 deepseek-flash 支持识图": "DeepSeek's deepseek-flash reads images",
    "glm-4.6v-flash 免费；能力更强的有 glm-4.6v、glm-5v-turbo": "glm-4.6v-flash is free; glm-4.6v and glm-5v-turbo are stronger",
    "也可使用 qwen3.8-max 等自身支持识图的模型": "Models that read images themselves, such as qwen3.8-max, work too",
    "kimi-k3、kimi-k2.6 均支持识图": "kimi-k3 and kimi-k2.6 both read images",
    "未知的 AI 服务商": "Unknown AI provider",
    "接口地址须以 http:// 或 https:// 开头，例如 https://api.deepseek.com": "The endpoint must start with http:// or https://, for example https://api.deepseek.com",
    "API Key 保存失败": "Couldn't save the API key",
    "接口地址重定向次数过多": "The endpoint redirected too many times",
    "接口地址已更改：已保存的 API Key 仅用于原地址，请重新填写新地址的 Key": "The endpoint was changed. The saved API key is only used for the old address; enter the key for the new one",
    "尚未配置 AI 服务，请在「AI 服务」中选择服务商并填写 API Key": "No AI service is set up yet. Choose a provider and enter an API key under “AI service”",
    "未填写接口地址": "No endpoint entered",
    "未填写 API Key": "no API key entered",
    "已停止": "Stopped",
    "对话内容已超出模型的上下文长度": "The conversation is longer than the model's context",
    "API Key 不正确或已失效，或无权使用该模型": "The API key is wrong or expired, or it may not use this model",
    "账户余额或额度不足": "The account is out of balance or quota",
    "接口地址或模型名称不正确": "The endpoint or the model name is wrong",
    "请求过于频繁，或额度已用尽": "Too many requests, or the quota is used up",
    "请求未被接受（模型名称不正确，或该模型不支持工具调用）": "The request was not accepted (the model name is wrong, or the model does not support tool use)",
    "服务端出错，请稍后重试": "The service had an error. Try again later",
    "服务拒绝了请求": "The service refused the request",
    "服务返回": "The service said",
    "该服务未提供模型列表，请直接填写模型名称": "This service offers no model list. Type the model name instead",
    "未选择模型，请在「AI 服务」中填写模型名称，或点击「选择模型」选取": "No model chosen. Enter a model name under “AI service”, or click “Choose model”",
    "无法解析响应内容，该地址可能不是 OpenAI 兼容接口": "the answer couldn't be read. This address may not be an OpenAI-compatible API",
    "无法解析响应内容，该地址可能不是 Anthropic 兼容接口": "the answer couldn't be read. This address may not be an Anthropic-compatible API",
    "回答过长被截断：请更换输出上限更高的模型，或拆分要求后重试": "The answer was too long and got cut off. Use a model with a higher output limit, or split up the request and try again",
    "请先选择 AI 服务商": "Choose an AI provider first",
