    "该工程的 Unity 插件为旧版，不支持截图：请在流水线页点击「更新」，待 Unity 编译完成后重试": "This project's Unity plugin is an old version that can't take screenshots. Click “Update” on the Pipeline tab and try again once Unity has compiled",
