    "隐藏的衣服同样计入：请移除不常用的衣服，或让同款不同配色的衣服共用一份物理（只装配一件，其余配色改为换色开关）": "Hidden outfits count too: remove outfits you rarely use, or let the colors of one outfit share one set of physics (fit only one; make the other colors color toggles)",
    "丢失的脚本": "Missing scripts",
    "这些物体上有脚本丢失的组件，说明该脚本所属的插件没有安装，带着它上传会失败或功能缺失": "These objects carry components whose script is missing, which means the plugin the script belongs to is not installed. Uploading like this fails or loses features",
    "请在 ALCOM 或 VCC 中为工程安装对应的插件（常见的是 Modular Avatar、VRCFury）；确认不再需要时，可在 Unity 的 Inspector 中移除该组件": "Install the plugin into the project in ALCOM or VCC (usually Modular Avatar or VRCFury). If you are sure it is no longer needed, remove the component in Unity's Inspector",
    "菜单单页的控件": "Controls on one menu page",
    "菜单的一页最多放 8 个控件，超出时无法上传": "A menu page holds 8 controls at most; with more, the upload fails",
    "请在 Unity 中打开对应的菜单资产，把多出的控件移入子菜单": "Open the menu asset in Unity and move the extra controls into a submenu",
    "主菜单": "Main menu",
