    "着色器不受支持": "shader not supported",
    "粉色或缺失的材质": "Pink or missing materials",
    "这些材质在游戏中会显示为粉色": "These materials show pink in game",
    "多数情况是着色器插件没有安装：请在 ALCOM 或 VCC 中为工程安装对应的着色器（如 lilToon、Poiyomi），待 Unity 编译完成后重新体检": "Mostly the shader package is not installed: install the shader into the project in ALCOM or VCC (lilToon, Poiyomi …) and run the check again once Unity has compiled",
    "材质槽为空时，请在 Unity 中为该网格重新指定材质": "Where a material slot is empty, give that mesh a material again in Unity",
