    "三角面数超出 Poor 档的上限": "The triangle count is over the limit for Poor",
    "可移除不常用的衣服和配饰，或安装 Avatar Optimizer（AAO），在构建时自动移除被遮挡的网格": "Remove outfits and accessories you rarely use, or install Avatar Optimizer (AAO), which removes hidden meshes at build time",
    "蒙皮网格偏多": "There are a lot of skinned meshes",
    "安装 Avatar Optimizer（AAO）并在模型上添加 Trace And Optimize 组件后，构建时会自动合并网格": "Install Avatar Optimizer (AAO) and add a Trace And Optimize component to the avatar; meshes are then merged at build time",
