    "安装 Avatar Optimizer（AAO）并在模型上添加 Trace And Optimize 组件后，构建时会自动合并相同的材质槽": "Install Avatar Optimizer (AAO) and add a Trace And Optimize component to the avatar; identical material slots are then merged at build time",
    "骨骼偏多": "There are a lot of bones",
    "每件衣服都带着一套骨骼：可移除不常用的衣服，或安装 Avatar Optimizer（AAO），在构建时自动移除无用的骨骼": "Every outfit brings a set of bones. Remove outfits you rarely use, or install Avatar Optimizer (AAO), which removes unused bones at build time",
    "PhysBone 组件偏多": "There are a lot of PhysBone components",
    "隐藏的衣服同样计入：可移除不常用的衣服，或让同款不同配色的衣服共用一份物理": "Hidden outfits count too: remove outfits you rarely use, or let the colors of one outfit share one set of physics",
    "受 PhysBone 影响的骨骼偏多": "A lot of bones are moved by PhysBones",
    "头发、尾巴和飘带占得最多，可移除不常用的衣服，或让同款不同配色的衣服共用一份物理": "Hair, tails and ribbons take the most. Remove outfits you rarely use, or let the colors of one outfit share one set of physics",
    "PhysBone 碰撞体偏多": "There are a lot of PhysBone colliders",
    "可移除不常用的衣服，或在 PhysBone 组件中去掉不需要的碰撞体": "Remove outfits you rarely use, or take colliders you don't need out of the PhysBone components",
    "PhysBone 碰撞检测次数偏多": "There are a lot of PhysBone collision checks",
    "可在 PhysBone 组件中减少碰撞体，或移除不常用的衣服": "Use fewer colliders in the PhysBone components, or remove outfits you rarely use",
    "实时灯光对性能影响很大，建议移除模型上的灯光": "Realtime lights cost a lot of performance. Consider removing the lights on the avatar",
    "粒子系统偏多，建议移除不需要的特效": "There are a lot of particle systems. Consider removing effects you don't need",
    "粒子数量偏多，建议降低粒子系统的 Max Particles": "There are a lot of particles. Consider lowering Max Particles of the particle systems",
    "贴图显存偏高": "Texture memory is high",
