    "请检查是否有物体离模型很远，或网格的 Bounds 被设置得过大": "Check whether some object is far from the avatar, or a mesh's Bounds are set too large",
    "该项超出 Poor 档的上限，模型的整体评级因此为 Very Poor，部分玩家的性能设置会默认不显示这类模型": "This figure is over the limit for Poor, which makes the avatar's overall rank Very Poor. Some players' performance settings hide such avatars by default",
