    // --- 1.7.6: check-up fixes and report ---
    "贴图降到 2048": "Textures down to 2048",
    "移除灯光": "Remove lights",
    "移除丢失的脚本": "Remove missing scripts",
    "改动贴图的导入设置并重新导入，可恢复": "Changes the textures' import settings and reimports them; can be restored",
    "仅在确认这些组件已不再需要时使用；若是插件未安装，请先安装插件": "Only when you are sure these components are no longer needed. If a plugin is not installed, install it instead",
    "这些贴图不在 Assets 文件夹内，或没有可调整的导入设置": "these textures are not in the Assets folder, or have no import settings to change",
    "部分已恢复": "Partly restored",
    "贴图的导入设置对整个工程生效，使用这些贴图的其他模型和场景也会随之改变": "A texture's import settings apply to the whole project: other avatars and scenes that use these textures change too",
    "如果脚本丢失是因为插件（Modular Avatar、VRCFury 等）没有安装或编译出错，请不要移除，应先安装或修复该插件：移除后，这些组件上的设置（衣服的装配、菜单项等）在场景保存后无法找回，重新安装插件也不会恢复": "If the scripts are missing because a plugin (Modular Avatar, VRCFury and the like) is not installed or does not compile, do not remove them; install or repair the plugin instead. Once removed, the settings on these components (how outfits are fitted, menu items and so on) are lost when the scene is saved, and reinstalling the plugin does not bring them back",
    "保存场景前可在 Unity 中按 Ctrl+Z 或点击「撤销上一步」撤销": "Until the scene is saved, Ctrl+Z in Unity or “Undo last step” takes it back",
    "确认这些组件已不再需要，是否继续？": "Are these components really no longer needed? Continue?",
    "将把模型用到的全部 4096 像素贴图的 Max Size 改为 2048 并重新导入": "Sets Max Size to 2048 on every 4096 px texture the avatar uses and reimports them",
    "导入设置不在 Unity 的撤销记录中，处理后可在体检面板中点击「恢复」改回原设置": "Import settings are not in Unity's undo history; after the fix, “Restore” in the pre-upload check panel puts the old settings back",
    "会移除模型下丢失脚本的组件": "It removes the components with missing scripts under the avatar",
    "保存场景前可用 Ctrl+Z 撤销": "Until the scene is saved, Ctrl+Z takes it back",
