    // --- 1.8.0: DeepSeek's thinking, the run's limit with the cache weighed, public holidays off-peak ---
    "在 platform.deepseek.com 申请 API Key。模型：deepseek-flash（推荐：DeepSeek 最新的 Flash 模型，能力和价格都优于 deepseek-v4-pro，支持识图）、deepseek-v4-pro（上一代，价格约为 deepseek-flash 的 3～4 倍，不支持识图，截图时自动由 deepseek-flash 代为描述）。旧名称 deepseek-chat / deepseek-reasoner / deepseek-v4-flash 已停用": "Get an API key at platform.deepseek.com. Models: deepseek-flash (recommended: DeepSeek's newest Flash model, stronger and cheaper than deepseek-v4-pro, reads images), deepseek-v4-pro (the previous generation, about 3–4 times the price of deepseek-flash, no vision; deepseek-flash describes screenshots for it). The old names deepseek-chat / deepseek-reasoner / deepseek-v4-flash are retired",
    "DeepSeek 在北京时间工作日 9:00–12:00、14:00–18:00 为高峰时段，价格为其余时段的 2 倍；法定节假日全天按低峰计（按国务院公布的放假安排，尚未公布的年份按工作日估算）": "DeepSeek's peak hours are 9:00–12:00 and 14:00–18:00 on weekdays (Beijing time), at twice the price; China's public holidays count as off-peak all day (by the State Council's published arrangement; a year not yet published is estimated as working days)",
    "设置了价格的模型，缓存命中的 tokens 按价格折算计入（DeepSeek 约为 1/50）": "For a model with a price, tokens read from the cache count at their price's share (about 1/50 for DeepSeek)",
    "思考强度": "Thinking",
    "标准": "Standard",
    "快速": "Fast",
    "深度": "Deep",
    "不思考": "No thinking",
    "按 AI 服务的设置": "As set in AI provider",
    "推荐。对话和菜单方案按 DeepSeek 的默认强度思考（high），检查结果时用 low，回答更快": "Recommended. The conversation and the menu plan think at DeepSeek's default (high); checking the result uses low, for a quicker answer",
    "全部用 low：更快、更省，复杂的改模要求可能完成得不如「标准」": "Everything at low: quicker and cheaper; complex modding requests may come out less well than with Standard",
    "对话和菜单方案用 max，检查结果用 high：更慢、输出更多，适合复杂的改模要求": "The conversation and the menu plan at max, checking the result at high: slower and longer answers, for complex modding requests",
    "不思考，直接回答：最快最省，菜单方案和改模的质量会下降": "Answers without thinking: the quickest and cheapest, but menu plans and modding get worse",
    "只对 DeepSeek 官方接口（api.deepseek.com）生效；各档的效果可在「AI 用量与花费」的评测里比较": "Applies to DeepSeek's own API (api.deepseek.com) only; the levels can be compared in the evaluation under AI usage and cost",
    "思考强度格式有误": "The thinking level is malformed",
