    "AI 服务选择 DeepSeek 时生效：素材名和商品说明先用它翻译（不可用时改用必应翻译），分类、适配素体、风格拿不准的素材由它看 Booth 信息补判": "Works when DeepSeek is the AI provider: asset names and product descriptions are translated by it first (Bing when it is unavailable), and assets whose kind, base body or style is unclear get them from it, by their Booth information",
