    "自动修复吗？": "Fix it automatically?",
    "修复方式：穿着这件衣服时隐藏被它盖住的身体（优先用素体自带的收缩形态键，没有时用 Modular Avatar 的 Mesh Cutter 裁掉），衣服和素体本身不改；修复后重新检测，没有改善就自动撤回": "How: while this outfit is worn, the body it covers is hidden (with the base's own shrink blend shapes, or else cut away with Modular Avatar's Mesh Cutter); the outfit and the base themselves aren't changed. It's measured again afterwards and taken back if it didn't help",
