    "该工程的 Unity 插件为旧版，不支持自动修复：请在流水线页点击「更新」，待 Unity 编译完成后重试": "This project's Unity plugin is an old version without auto-fixes. Click “Update” on the Pipeline tab and try again once Unity has compiled",
    "该工程的 Unity 插件为旧版，不支持调整形态键：请在流水线页点击「更新」，待 Unity 编译完成后重试": "This project's Unity plugin is an old version that can't adjust blend shapes. Click “Update” on the Pipeline tab and try again once Unity has compiled",
    "该工程的 Unity 插件为旧版，不支持制作表情：请在流水线页点击「更新」，待 Unity 编译完成后重试": "This project's Unity plugin is an old version that can't make expressions. Click “Update” on the Pipeline tab and try again once Unity has compiled",
