    "看到的是 Unity 编辑模式下的样子：菜单开关附带的形态键变化、骨骼物理（裙摆、头发的摆动）不会显示。": "This is how the avatar looks in Unity's Edit mode: blend shapes the menu toggles change and bone physics (skirts and hair swinging) aren't shown.",
