    "该工程的 Unity 插件为旧版，不支持3D 试衣间：请在流水线页点击「更新」，待 Unity 编译完成后重试": "This project's Unity plugin is an old version without the 3D fitting room. Click “Update” on the Pipeline tab and try again once Unity has compiled",
    // --- 1.8.0: 照图配装 (the nearest assets to a picture) ---
    "给一张图（别人的模型、商品图、截图），AI 从素材库里找出最接近的衣服、头发和配饰": "Give a picture (someone's avatar, a shop's image, a screenshot) and the AI finds the nearest outfits, hair and accessories in the Library",
