    "参考图": "Reference picture",
    "把图片拖到这里，或按 Ctrl+V 粘贴": "Drop a picture here, or paste it with Ctrl+V",
    "别人的模型截图、Booth 商品图、照片都可以": "Someone's avatar, a Booth product image or a photo will do",
    "AI 正在看图，并在素材库中查找…": "The AI is looking at the picture and searching the Library…",
    "已穿上": "Worn",
