    "加入流水线": "Add to the pipeline",
    "在素材库中打开，可一键导入到工程": "Open it in the Library, where it can be imported into the project in one click",
    "结果会显示在这里。": "The results appear here.",
    "补充说明（选填），例如：只要衣服；想要更可爱一点": "A note (optional), e.g. only the outfit; a bit cuter",
    "开始配装": "Find the look",
    "AI 先看图说出衣服、头发和配饰的样子，再从素材库里找最接近的（会参考封面）。需要能看图的 AI；当前模型看不了图时会用「识图」中设置的视觉模型。": "The AI first says what the outfit, hair and accessories in the picture look like, then finds the nearest in the Library (its covers too). It needs an AI that sees pictures; when the current model can't, the vision model set under “Vision” is used.",
    "未能完成照图配装": "The look couldn't be matched",
    "识图已关闭：照图配装需要能看图的 AI，请在「AI 服务」的「识图」中开启": "Vision is off: matching a look needs an AI that sees pictures. Turn it on under “Vision” in “AI service”",
    "当前 AI 模型看不了图，也没有设置视觉模型：请在「AI 服务」的「识图」中设置一个能看图的模型": "The current AI model can't see pictures and no vision model is set up: set one under “Vision” in “AI service”",
