    "时光机": "Time machine",
    "每次运行流水线、AI 第一次修改模型之前，自动记下模型当时的样子；可以一键回到其中任意一刻": "Before every pipeline run, and before the AI first changes the avatar in a chat, the avatar is kept as it was; go back to any of those moments with one click",
    "工程时光机": "Project time machine",
    "无法读取时光机": "Could not read the time machine",
