    "和现在的模型相比，身上的物体和菜单没有变化（材质、形态键等细节的改动不在比较之列）。": "Compared with the avatar now, the objects on it and its menu are the same (changes to materials, blendshapes and other details are not compared).",
    "这一刻之后导入的文件夹，现在的模型不再用到的话，可以移到回收站（「还原前」的模型可能因此缺少文件）：": "Folders imported after this moment can go to the Recycle Bin if the avatar no longer uses them (the \"before restore\" avatar may then miss files):",
    "移到回收站": "Move to Recycle Bin",
    "在 Unity 中按 Ctrl+Z 可撤销；确认无误后再保存场景": "Press Ctrl+Z in Unity to undo it; save the scene once everything looks right",
    "没有子物体。": "No child objects.",
    "当时身上": "On it then",
    "默认隐藏：": "Hidden by default:",
    "和现在相比": "Compared with now",
    "回到这一刻": "Go back to this moment",
    "删除这个快照": "Delete this snapshot",
    "回到这一刻：把当时的模型放回场景中原来的位置，现在的模型改名为「（还原前）」并隐藏，不删除任何东西。场景不会自动保存。": "Go back to this moment: the avatar as it was goes back where it stood in the scene, and the avatar of now is renamed \"(before restore)\" and hidden. Nothing is deleted. The scene is not saved for you.",
    "还没有记下的时刻。每次运行流水线、AI 第一次修改模型之前，会自动记下模型当时的样子；也可以点击下方「保存当前状态」。": "No moments kept yet. Before every pipeline run, and before the AI first changes the avatar, the avatar is kept as it was; you can also click \"Save current state\" below.",
    "备注（选填），例如：换发型前": "Note (optional), e.g. before changing the hair",
    "保存当前状态": "Save current state",
    "已记下当前的模型": "The avatar is kept as it is now",
    "未能还原": "Could not restore",
    "未能删除": "Could not delete",
    "未能保存": "Could not save",
    "未能移到回收站": "Could not move to the Recycle Bin",
    "已移到回收站": "Moved to the Recycle Bin",
    "需要时可从回收站还原。": "You can restore them from the Recycle Bin if needed.",
    "当时的模型将放回场景，现在的模型改名为「（还原前）」并隐藏，不删除任何东西。可在 Unity 中按 Ctrl+Z 撤销。": "The avatar as it was goes back into the scene; the avatar of now is renamed \"(before restore)\" and hidden. Nothing is deleted. Ctrl+Z in Unity undoes it.",
