    // --- Quest 版 (1.8.0) ---
    "设置 Quest（安卓）版": "Set up the Quest (Android) version",
    "查看 Quest（安卓）版的情况": "Check the Quest (Android) version",
    "下次在 Unity 中打开工程时会自动导入": "Unity imports it the next time the project is opened",
    "Unity 正在导入并编译（约一两分钟）": "Unity is importing and compiling (a minute or two)",
    "等待 Unity 导入超时": "Timed out waiting for Unity to import it",
    "插件已放入工程，但 Unity 还没有加载它：请切换到 Unity 窗口，等待编译完成（如有红色报错需先解决）": "The plugin is in the project, but Unity has not loaded it yet: switch to the Unity window and wait for compiling to finish (fix any red errors first)",
    "Quest 版设置": "Quest version setup",
    "Quest 设置前": "Before the Quest setup",
    "未找到 Unity Hub": "Unity Hub was not found",
    "未连接 Unity": "Not connected to Unity",
    "AI 请求把 VRCQuestTools（kurotu 制作，MIT 许可）安装到该工程，用来制作 Quest（安卓）版。": "The AI asks to install VRCQuestTools (by kurotu, MIT license) into this project to make the Quest (Android) version.",
    "会从它的 VPM 仓库下载，放进工程的 Packages 文件夹并写入 vpm-manifest.json（和在 ALCOM 中添加插件一样），之后 Unity 会导入并编译一两分钟。": "It is downloaded from its VPM repository into the project's Packages folder and added to vpm-manifest.json (just like adding it in ALCOM); Unity then imports and compiles it for a minute or two.",
    "玩家未同意安装": "The player did not agree to install it",
    "安装 VRCQuestTools": "Install VRCQuestTools",
    "安装未完成": "The install did not finish",
    "工程未安装 VRCQuestTools": "VRCQuestTools is not installed in the project",
    "无法估算安卓版评级": "Could not estimate the Android rank",
    "制作 Quest（安卓）版时使用（可选）": "For making the Quest (Android) version (optional)",
    "工程的 Assets/KRT/VRCQuestTools 中有旧版 VRCQuestTools（以 unitypackage 导入的）：请先在 ALCOM 中处理，或删除该文件夹后重试": "The project has an old VRCQuestTools in Assets/KRT/VRCQuestTools (imported as a unitypackage): deal with it in ALCOM first, or delete that folder and try again",
    "工程中没有 Packages/vpm-manifest.json：不是由 VCC / ALCOM 管理的工程，请在 ALCOM 中添加插件": "The project has no Packages/vpm-manifest.json: it is not managed by VCC / ALCOM, so add the plugin in ALCOM",
    "MioVRCA Quest 设置": "MioVRCA Quest setup",
    "工程中还没有可用的 VRCQuestTools：请先安装（安装后需等 Unity 编译完成）": "VRCQuestTools is not available in the project yet: install it first (and wait for Unity to finish compiling)",
    "用 VRCQuestTools 制作 Quest（安卓）版：一键安装和设置，挑选安卓版保留的 PhysBone，并预估安卓版的评级。PC 版不受影响": "Make the Quest (Android) version with VRCQuestTools: install and set up with one click, pick the PhysBones the Android version keeps, and see the rank it would get. The PC version is not changed",
    "Quest 版": "Quest version",
    "能大幅减少面数和材质；这些衣服的菜单开关在安卓版里不起作用。": "This cuts polygons and materials a lot; the menu toggles of those outfits do nothing on Android.",
    "应用到模型": "Apply to the avatar",
    "按程序建议": "Use the suggestion",
    "超过安卓的上限：VRChat 会去掉这一类的全部组件。请再少留一些。": "Over Android's limit: VRChat removes every component of that kind. Keep fewer.",
    "显示的是模型上已有的标记": "Showing the marks already on the avatar",
    "显示的是程序的建议（头发、裙子、尾巴、耳朵优先）": "Showing the suggestion (hair, skirts, tails and ears first)",
    "上传完把平台切回 Windows，再继续改模。": "After the upload, switch the platform back to Windows before you keep editing.",
    "先在 VRChat SDK 面板重新上传一次 PC 版：让 PC 和安卓版的 PhysBone 同步。": "First upload the PC version once more from the VRChat SDK panel, so PhysBones stay in sync between PC and Android.",
    "在 SDK 面板的 Selected Platform 中选 Android。第一次切换要重新导入全部素材，大工程可能需要十几分钟。": "In the SDK panel, choose Android under Selected Platform. The first switch reimports every asset, which can take over ten minutes for a big project.",
    "点 Build and Publish：VRCQuestTools 在构建时自动转换。": "Click Build and Publish: VRCQuestTools converts the avatar during the build.",
    "由 VRCQuestTools（kurotu，MIT）在上传安卓版时自动转换：材质换成安卓可用的着色器，去掉安卓不支持的组件。PC 版不受影响。": "VRCQuestTools (kurotu, MIT) converts the avatar when the Android version is uploaded: materials switch to shaders Android allows, and components Android does not support are removed. The PC version is not changed.",
    "安卓版保留的物理": "Physics the Android version keeps",
    "评级预估": "Estimated rank",
    "上传": "Upload",
    "Quest（安卓）版": "Quest (Android) version",
    "设置可在 Unity 中按 Ctrl+Z 撤销，也可在「时光机」中回到设置前": "Undo the setup with Ctrl+Z in Unity, or go back to before it in \"Time machine\"",
    "无法打开 Unity Hub": "Could not open Unity Hub",
    "将 VRCQuestTools（kurotu 制作，MIT 许可）安装到该工程？": "Install VRCQuestTools (by kurotu, MIT license) into this project?",
    "会从它的 VPM 仓库下载，放进工程的 Packages 文件夹并写入 vpm-manifest.json（和在 ALCOM 中添加插件一样）。Unity 打开着的话会接着导入并编译一两分钟。": "It is downloaded from its VPM repository into the project's Packages folder and added to vpm-manifest.json (just like adding it in ALCOM). If Unity is open, it then imports and compiles for a minute or two.",
    "未能安装": "Could not install",
    "未能设置": "Could not set it up",
    "已应用到模型": "Applied to the avatar",
    "受影响的骨骼": "Affected bones",
    "（Unity 还没有加载：请切换到 Unity 窗口等待编译完成）": "(Unity has not loaded it yet: switch to the Unity window and wait for compiling to finish)",
    "Android 构建模块": "Android build module",
    "打开 Unity Hub": "Open Unity Hub",
    "在 Unity 中打开工程后，可以设置模型并查看安卓版的评级预估。": "Open the project in Unity to set up the avatar and see the Android rank estimate.",
    "模型设置": "Avatar setup",
    "一键设置": "Set up",
    "在模型上加 VRCQuestTools 的设置组件，并按下面的选择标记安卓版去掉的物理": "Adds VRCQuestTools's settings component to the avatar and marks the physics the Android version leaves out, as chosen below",
    "请先安装 VRCQuestTools": "Install VRCQuestTools first",
    "该 SDK 没有性能计算器，无法估算。": "This SDK has no performance calculator, so there is no estimate.",
    "按模型上已应用的选择估算（还没设置时按程序的建议）。材质槽数不变（VRCQuestTools 只换着色器）；贴图由 VRCQuestTools 重新生成，显存以上传时 SDK 显示的为准。安卓版的上传上限：下载 10 MB、解压后 40 MB。": "Estimated with the choice applied to the avatar (or the suggestion before it is set up). The number of material slots stays (VRCQuestTools only changes shaders); VRCQuestTools makes the textures anew, so go by the SDK's figure for texture memory when uploading. Android uploads are limited to 10 MB to download and 40 MB uncompressed.",
    "安卓默认只显示 Medium 及以上的模型：Quest 玩家要在你的名片上点「显示模型」才看得到（其余时候显示为备用模型）。大多数日系模型的安卓版都是这样。": "By default Android only shows avatars rated Medium or better: Quest players have to click \"Show Avatar\" on you to see it (otherwise they see a fallback). That is how it goes for most Japanese avatars' Android versions.",
    "（模型根物体）": "(the avatar's root object)",
