    "社区方案库中找不到该方案的文件，请刷新列表": "The community presets have no file for this preset. Refresh the list",
    // --- 1.8.0: measured fits and the author tool (miovrca.json) ---
    "社区实测数据": "Community fit data",
    "查看和分享…": "View and share…",
    "流水线验收时记下每件衣服在素体上是否穿模、怎样修好的，下次装配同一件衣服时自动套用；分享给社区后，其他玩家装配时也能用上": "The pipeline's review notes whether each outfit clips on the base and how it was fixed, and uses that the next time the same outfit is fitted. Shared with the community, it helps other players fit it too",
    "作者说明": "Author's file",
    "本机记录": "This computer's record",
    "社区实测": "Community data",
    "没有穿模": "No clipping",
    "穿着时设置": "While worn, sets",
    "裁掉被盖住的身体": "Cuts away the covered body",
    "删除这条记录": "Delete this record",
    "已分享": "Shared",
    "未分享": "Not shared",
    "仅本机": "This computer only",
    "没有 Booth 商品编号的记录不分享（其他玩家无法确认是同一件衣服）": "Records without a Booth item number are not shared (other players couldn't tell it is the same outfit)",
    "流水线验收时，会记下每件衣服在素体上是否穿模、怎样修好的（例如穿着时设置哪些收缩形态键）": "During the pipeline's review, whether each outfit clips on the base and how it was fixed (such as which shrink blendshapes are set while it is worn) is noted",
    "下次在同一个素体上装配同一件衣服，会先套用这些设置再验收": "The next time the same outfit is fitted on the same base, these settings are applied before the review",
    "结果": "Result",
    "做法": "How",
    "还没有记录": "No records yet",
    "运行流水线并完成验收后，这里会列出每件衣服的结果": "After a pipeline run and its review, each outfit's result is listed here",
    "分享给社区": "Share with the community",
    "分享的内容只有：Booth 商品编号、衣服和 prefab 的名称、素体名称、穿模的顶点数、用到的形态键名称": "What is shared: the Booth item number, the outfit's and prefab's names, the base's name, the clipping vertex counts and the blendshape names used — nothing else",
    "不包含工程路径、账号等个人信息": "No project paths, accounts or other personal information",
    "需要登录 GitHub，在打开的页面中提交": "You need to sign in to GitHub and submit on the page that opens",
    "无法分享": "Couldn't share",
    "分享码较长，已复制：请在打开的页面中粘贴到「实测数据分享码」一栏": "The share code is long, so it was copied: paste it into the “Fit data share code” field of the page that opened",
    "清空本机的全部实测记录？已分享给社区的不受影响": "Clear all fit records on this computer? What was shared with the community is not affected",
    "实测数据": "Fit data",
    "常用：穿着时设置": "Usually: while worn, sets",
    "在这些素体上装配这件衣服时，流水线会先套用常用的形态键设置，再做验收": "When this outfit is fitted on these bases, the pipeline applies the usual blendshape settings first, then reviews it",
    "本机": "This computer",
    "作者工具": "Author tool",
    "为素材生成 miovrca.json…": "Make a miovrca.json for an asset…",
    "素材作者用：写一份素材说明文件放进素材包，玩家用 MioVRCA 装配时，会按它选用对应素体的版本、设置穿着时的形态键、生成部件开关": "For asset authors: put a description file into your package, and when a player fits it with MioVRCA, it picks the version for their base, sets the blendshapes while it is worn and builds the part switches",
    "作者工具：素材说明文件": "Author tool: asset description file",
    "为你自己的素材写一份素材说明文件（miovrca.json），放进素材包一起发布": "Write a description file (miovrca.json) for an asset of your own and publish it in the package",
    "玩家用 MioVRCA 装配时，会按它选用对应素体的版本、设置穿着时的形态键、生成部件开关": "When a player fits the asset with MioVRCA, it picks the version for their base, sets the blendshapes while it is worn and builds the part switches",
    "请先在「工程」页添加工程": "Add a project on the “Projects” tab first",
    "正在读取文件夹…": "Reading the folder…",
    "文件夹中已有 miovrca.json，下面是它的内容": "The folder has a miovrca.json already; this is what it says",
