    "Unity 未打开，无法读取 prefab 的网格名：部件需要手动填写": "Unity is not open, so the prefabs' mesh names can't be read: fill in the parts by hand",
    "未指定": "Not set",
    "商品页（选填）": "Shop page (optional)",
    "每个素体用哪个 prefab": "Which prefab is for each base",
    "穿着时要设置的身体形态键写成「形态键名=数值」，多个用逗号分开，例如 Shrink_Chest=100, Shrink_Leg=100": "The body's blendshapes to set while it is worn go as “name=value”, separated by commas, e.g. Shrink_Chest=100, Shrink_Leg=100",
