    // --- checkup advice for an avatar that has Trace And Optimize ---
    "三角面数超出 Poor 档的上限。模型已有 Trace And Optimize，上传构建时会移除被遮挡的网格，实际数值以构建后为准；仍超出时可移除不常用的衣服和配饰。": "Triangles exceed the Poor limit. The avatar has Trace And Optimize, which removes hidden meshes when it is built for upload; the built figure is what counts. If it is still over, remove clothes and accessories you rarely use.",
    "蒙皮网格偏多。模型已有 Trace And Optimize，上传构建时会自动合并网格，实际数值以构建后为准。": "Many skinned meshes. The avatar has Trace And Optimize, which merges meshes when it is built for upload; the built figure is what counts.",
    "网格偏多。模型已有 Trace And Optimize，上传构建时会自动合并网格，实际数值以构建后为准。": "Many meshes. The avatar has Trace And Optimize, which merges meshes when it is built for upload; the built figure is what counts.",
    "材质槽偏多。模型已有 Trace And Optimize，上传构建时会自动合并相同的材质槽，实际数值以构建后为准。": "Many material slots. The avatar has Trace And Optimize, which merges identical material slots when it is built for upload; the built figure is what counts.",
    "骨骼偏多。模型已有 Trace And Optimize，上传构建时会自动移除无用的骨骼；仍超出时可移除不常用的衣服。": "Many bones. The avatar has Trace And Optimize, which removes unused bones when it is built for upload. If it is still over, remove clothes you rarely use.",
